package taxi.blizz.files.internal;

import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.util.regex.Pattern;
import org.springframework.stereotype.Component;

/**
 * Files on the local disk below {@code blizz.files.local-dir}; call recordings below
 * {@code blizz.files.call-recordings-dir} when it is set. Keys are generated by the server and validated, so a key can
 * never point outside its directory.
 */
@Component
class LocalFileStorage implements FileStorage {

    private static final Pattern KEY = Pattern.compile("^[a-z0-9_]+(/[a-z0-9-]+)+$");

    private static final String CALL_RECORDINGS = "call_recording/";

    private final Path root;
    private final Path recordingsRoot;
    private final Path staging;

    LocalFileStorage(FilesProperties properties) throws IOException {
        this.root = properties.localDir().toAbsolutePath().normalize();
        String recordings = properties.callRecordingsDir();
        this.recordingsRoot = recordings == null || recordings.isBlank() ? root
                : Path.of(recordings.strip()).toAbsolutePath().normalize();
        this.staging = root.resolve("staging");
        Files.createDirectories(staging);
        Files.createDirectories(recordingsRoot);
    }

    private Path staged(String key) {
        resolve(key); // Validate before deriving any private path.
        return staging.resolve(
                java.util.UUID.nameUUIDFromBytes(key.getBytes(java.nio.charset.StandardCharsets.UTF_8)) + ".bin");
    }

    @Override
    public Path reserve(String key) throws IOException {
        Path raw = Files.createFile(staged(key), java.nio.file.attribute.PosixFilePermissions.asFileAttribute(
                java.nio.file.attribute.PosixFilePermissions.fromString("rw-------")));
        try {
            Files.createFile(raw.resolveSibling(raw.getFileName() + ".sealed"),
                    java.nio.file.attribute.PosixFilePermissions.asFileAttribute(
                            java.nio.file.attribute.PosixFilePermissions.fromString("rw-------")));
        } catch (IOException ex) {
            Files.deleteIfExists(raw);
            throw ex;
        }
        return raw;
    }

    @Override
    public Path stage(InputStream body, long maxBytes, String key) throws IOException, TooLargeException {
        Path target = staged(key);
        long written = 0;
        byte[] buffer = new byte[64 * 1024];
        try (OutputStream out = Files.newOutputStream(target, java.nio.file.StandardOpenOption.WRITE,
                java.nio.file.StandardOpenOption.TRUNCATE_EXISTING)) {
            int read;
            while ((read = body.read(buffer)) != -1) {
                written += read;
                if (written > maxBytes) {
                    throw new TooLargeException();
                }
                out.write(buffer, 0, read);
            }
        } catch (IOException | TooLargeException | RuntimeException e) {
            Files.deleteIfExists(target);
            throw e;
        }
        return target;
    }

    @Override
    public void store(Path staged, String key) throws IOException {
        Path target = resolve(key);
        Files.createDirectories(target.getParent());
        try {
            Files.move(staged, target, StandardCopyOption.ATOMIC_MOVE);
        } catch (AtomicMoveNotSupportedException otherDisk) {
            Path partial = target.resolveSibling(target.getFileName() + ".partial");
            Files.copy(staged, partial, StandardCopyOption.REPLACE_EXISTING);
            Files.move(partial, target, StandardCopyOption.ATOMIC_MOVE);
            Files.delete(staged);
        }
    }

    @Override
    public InputStream open(String key) throws IOException {
        return Files.newInputStream(resolve(key));
    }

    @Override
    public void clearStage(String key) throws IOException {
        Path raw = staged(key), finalPath = resolve(key);
        Files.deleteIfExists(raw);
        Files.deleteIfExists(raw.resolveSibling(raw.getFileName() + ".sealed"));
        Files.deleteIfExists(finalPath.resolveSibling(finalPath.getFileName() + ".partial"));
    }

    @Override
    public boolean delete(String key) throws IOException {
        Path raw = staged(key), target = resolve(key);
        boolean removed = false;
        try {
            removed |= Files.deleteIfExists(raw);
            removed |= Files.deleteIfExists(raw.resolveSibling(raw.getFileName() + ".sealed"));
            removed |= Files.deleteIfExists(target.resolveSibling(target.getFileName() + ".partial"));
            removed |= Files.deleteIfExists(target);
            return removed;
        } catch (IOException ex) {
            throw new DeletionFailure("File deletion failed", removed, ex);
        }
    }

    private Path resolve(String key) {
        if (!KEY.matcher(key).matches()) {
            throw new IllegalArgumentException("Invalid storage key");
        }
        Path base = key.startsWith(CALL_RECORDINGS) ? recordingsRoot : root;
        Path path = base.resolve(key).normalize();
        if (!path.startsWith(base)) {
            throw new IllegalArgumentException("Invalid storage key");
        }
        return path;
    }
}
